function binaryGap(n) {
  let longest = 0;
  let last = -1;

  for (let bit = 0; n > 0; bit++) {
    if ((n & 1) === 1) {
      if (last !== -1) {
        longest = Math.max(longest, bit - last);
      }
      last = bit;
    }
    n >>= 1;
  }
  return longest;
}

