function binaryGap(n) {
  const digits = n.toString(2);
  const ones = [];
  for (let i = 0; i < digits.length; i++) if (digits[i] === '1') ones.push(i);
  let answer = 0;
  for (let j = 1; j < ones.length; j++) answer = Math.max(answer, ones[j] - ones[j - 1]);
  return answer;
}

