function generate(rand, size) {
  const maxBits = size === 'large' ? 30 : 8;
  if (rand() < 0.4) return [1 + Math.floor(rand() * (size === 'large' ? 1e9 : 255))];
  // Only a few distinct set bits, so long runs of zeros appear.
  const count = 1 + Math.floor(rand() * 4);
  const bits = new Set();
  for (let c = 0; c < count; c++) bits.add(Math.floor(rand() * maxBits));
  let n = 0;
  for (const bit of bits) n += 2 ** bit;
  return [Math.min(n, 1e9)];
}
